    }
    when ACCESS_POLICY_AGENT_EVENT {
        set agent [ACCESS::policy agent_id]
        ACCESS::session data set session.custom.evtflow2_agent $agent
        log local0. "EVTFLOW2|run=EFD|event=ACCESS_POLICY_AGENT_EVENT|tmm=[TMM::cmp_group]:[TMM::cmp_unit]|probe=apm|agent=$agent|sid=[ACCESS::session sid]"
    }
